// Complete reverse extension for a fixed cut pair. Cover every old eight and every seven missed by the restored vertex.
use std::io::{self,BufRead};type A=[u32;26];type Edge=(usize,usize);
fn allow(a:&A,s:u32,es:&[Edge])->u64{let mut m=0;for(k,&(i,j))in es.iter().enumerate(){if a[i]&((1<<j)|a[j])==0 && !(s>>i&s>>j&1!=0) && a[i].count_ones()+(s>>i&1)<7 && a[j].count_ones()+(s>>j&1)<7{m|=1<<k}}m}
fn rec(a:A,s:u32,es:&[Edge],ds:&[u64],sel:u64,ban:u64,branches:&mut u64)->Option<u64>{let ok=allow(&a,s,es)&!ban;let mut best=0;let mut low=65;for &d in ds{if sel&d!=0{continue}let v=d&ok;let n=v.count_ones();if n==0{return None}if n<low{low=n;best=v}}if low==65{return Some(sel)}if low>1{*branches+=1}while best!=0{let k=best.trailing_zeros()as usize;best&=best-1;let(i,j)=es[k];let mut b=a;b[i]|=1<<j;b[j]|=1<<i;if let Some(x)=rec(b,s,es,ds,sel|1<<k,ban,branches){return Some(x)}}None}
fn main(){for l in io::stdin().lock().lines(){let x:Vec<usize>=l.unwrap().split_whitespace().map(|y|y.parse().unwrap()).collect();let mut a=[0u32;26];for j in 0..26{a[j]=x[4+j]as u32}let orig=a;let cuts=[(x[0],x[1]),(x[2],x[3])];for &(u,v)in &cuts{assert_ne!(a[u]>>v&1,0);a[u]^=1<<v;a[v]^=1<<u}let mut es=vec![];let mut joint=0;for j in 0..26{for i in 0..j{if !cuts.contains(&(i,j)) && a[i]&((1<<j)|a[j])==0{assert!(es.len()<64);if (orig[i]&orig[j]).count_ones()==2{joint|=1u64<<es.len()}es.push((i,j))}}}let mut sets=vec![0u32];for j in 0..26{for i in 0..sets.len(){let s=sets[i];if s&a[j]==0{sets.push(s|(1<<j))}}}let mut qs=vec![];for &q in &sets{let n=q.count_ones();if n==7||n==8{let mut m=0;for(k,&(i,j))in es.iter().enumerate(){if q>>i&q>>j&1!=0{m|=1u64<<k}}qs.push((if n==8{0}else{q},m))}}let mut ct=[0u64;4];let mut ex=vec![];let mut no_branch=0;let mut perm=0;for j in 0..26{if a[j].count_ones()>=7{perm|=1<<j}}for &s in &sets{if !(4..=7).contains(&s.count_ones())||s&perm!=0{continue}let ok=allow(&a,s,&es);let mut ds=vec![];let mut failed=false;for &(q,d)in &qs{if q&s!=0{continue}let v=d&ok;if v==0{failed=true;break}ds.push(v)}if failed{continue}ct[0]+=1;ds.sort_unstable();ds.dedup();ds.sort_by_key(|d|d.count_ones());let mut branches=0;if let Some(sol)=rec(a,s,&es,&ds,0,0,&mut branches){ct[1]+=1;let mut necessary=vec![];for k in 0..es.len(){if sol&joint&(1<<k)!=0 && rec(a,s,&es,&ds,0,1<<k,&mut 0).is_none(){necessary.push(es[k])}}if !necessary.is_empty(){ct[2]+=1}let all=std::env::var_os("RAMSEY_ALL_ROWS").is_some();if all||ex.is_empty()||!necessary.is_empty(){if !all{ex.clear()}ex.push(format!("[{}, {:?}, {:?}]",s,(0..es.len()).filter(|&k|sol>>k&1!=0).map(|k|vec![es[k].0,es[k].1]).collect::<Vec<_>>(),necessary.iter().map(|e|vec![e.0,e.1]).collect::<Vec<_>>()))}}else if branches==0{no_branch+=1}ct[3]+=branches}println!("{} {} {} {} {} {} {}",joint.count_ones(),ct[0],ct[1],ct[2],ct[3],no_branch,if std::env::var_os("RAMSEY_ALL_ROWS").is_some(){format!("[{}]",ex.join(","))}else{ex.first().cloned().unwrap_or_else(||"null".to_string())})}}
